472	            if (bankName == null || bankName.isBlank()) {
473	                throw new PaymentException(PaymentErrorCode.INVALID_BANK_INFO, "은행 이름은 필수입니다.");
474	            }
476	            try {
477	                Bank.valueOf(bankName.toUpperCase());
478	            } catch (IllegalArgumentException e) {
479	                throw new PaymentException(PaymentErrorCode.INVALID_BANK_INFO,
480	                        "지원하지 않는 은행입니다: " + bankName);
481	            }
482	        } catch (PaymentException e) {
483	            throw e; // 이미 PaymentException이면 그대로 전파
484	        } catch (Exception e) {
485	            throw new PaymentException(PaymentErrorCode.INVALID_BANK_INFO,
486	                    "은행 정보 검증 중 오류가 발생했습니다.", e);
